        Boolean mainHorizontal = RenderNode.stackMainHorizontal(parentComponent);
        if (mainHorizontal != null
                && RenderNode.fillsAxis(nodes, id, !mainHorizontal, false)) {
            derived.append("align-self:stretch;");
