            }
            String inner = name == null ? null : Icons.webInner(name);
            if (inner == null) {
                inner = Icons.webFallbackSvg();
            }
            String iconAria;
            String label = node.strings.get(Properties.LABEL);
            if (label != null && !label.isEmpty()) {
                iconAria = " role=\"img\" aria-label=\"" + Format.escape(label) + "\"";
            } else {
