package dev.pathland.server;


import dev.pathland.view.core.ThemeData;
import dev.pathland.view.core.View;

/**
 * The application's root-view factory — the single app-specific piece the server
 * runtime needs. A host (Spring Boot / Quarkus starter) provides one as a bean; the
 * runtime mounts a fresh root per session (views hold per-session {@code State}).
 *
 * <pre>{@code
 * @Bean PathlandApp pathlandApp() { return () -> new MyHomeView(); }
 * }</pre>
 */
@FunctionalInterface
public interface PathlandApp {

    /** A fresh root view for a new session. */
    View newRoot();

    /** The optional global theme (design-token overrides); {@code null} for none. */
    default ThemeData theme() {
        return null;
    }

    /**
     * Optional per-route document metadata for the SSR head (canonical URL,
     * Open Graph/Twitter cards, JSON-LD). Called before the first render with
     * the active route, so an app can make metadata route-specific.
     *
     * <p>Returned non-null fields override the host defaults built from the
     * request URL and {@code pathland.seo.*} config. The default returns no
     * overrides.
     */
    default PageMetadata pageMetadata(PageMetadataRequest request) {
        return PageMetadata.empty();
    }
}    }

    /** A valid crawler policy — never the SPA HTML fallback. */
    @GET
    @Path("/robots.txt")
    @Produces(MediaType.TEXT_PLAIN)
    public Response robots(@Context UriInfo uri) {
        String base = uri.getBaseUri().toString();
        String body = "User-agent: *\nAllow: /\nSitemap: " + base + "sitemap.xml\n";
        return Response.ok(body).build();
    }

    /** A one-entry sitemap for the app root (a host may mount more routes). */
    @GET
    @Path("/sitemap.xml")
    @Produces(MediaType.APPLICATION_XML)
    public Response sitemap(@Context UriInfo uri) {
        String loc = uri.getBaseUri().toString();
        String body = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">"
                + "<url><loc>" + loc + "</loc></url></urlset>\n";
        return Response.ok(body).build();
    }

    /**
     * Any other path (deep links) — a multi-segment catch-all. The negative lookahead
     * excludes a path that <em>starts</em> with the reserved {@code _pathland} prefix (the
     * global WebSocket + DOM client bundle, served by Quarkus static resources from
     * {@code META-INF/resources} before JAX-RS) and the Quarkus **non-application root**
     * ({@code /q/**} — health, metrics, …), which the framework serves. Per-app framework
     * paths ({@code /<app>/_pathland/...}, e.g. a mounted app's bundle) are intercepted
    public ResponseEntity<String> robots(HttpServletRequest request) {
        String base = baseUrl(request);
        return ResponseEntity.ok("User-agent: *\nAllow: /\nSitemap: " + base + "sitemap.xml\n");
