package dev.pathland.demo.docs;

import dev.pathland.server.PathlandApp;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Produces;
import jakarta.inject.Singleton;

/** The CDI producer for the Kotlin-authored docs site. */
@ApplicationScoped
public class DocsDemoApp {

    @Produces
    @Singleton
    PathlandApp docsApp() {
        return new DocsSite();
    }
}

package dev.pathland.demo.docs

import dev.pathland.docs.DocsLayout
import dev.pathland.docs.DocsPage
import dev.pathland.docs.DocsRepository
import dev.pathland.docs.Markdown
import dev.pathland.server.PageMetadata
import dev.pathland.server.PageMetadataRequest
import dev.pathland.server.PathlandApp
import dev.pathland.view.core.FontWeight
import dev.pathland.view.core.HorizontalAlignment
import dev.pathland.view.core.Roles
import dev.pathland.view.core.VerticalAlignment
import dev.pathland.view.core.View
import dev.pathland.view.dsl.Button
import dev.pathland.view.dsl.Color
import dev.pathland.view.dsl.Divider
import dev.pathland.view.dsl.Font
import dev.pathland.view.dsl.Grid
import dev.pathland.view.dsl.HStack
import dev.pathland.view.dsl.Image
import dev.pathland.view.dsl.NavigationStack
import dev.pathland.view.dsl.Spacer
import dev.pathland.view.dsl.Text
import dev.pathland.view.dsl.VStack
import dev.pathland.view.dsl.accessibilityRole
import dev.pathland.view.dsl.background
import dev.pathland.view.dsl.border
import dev.pathland.view.dsl.buttonStyle
import dev.pathland.view.dsl.font
import dev.pathland.view.dsl.fontSize
import dev.pathland.view.dsl.fontWeight
import dev.pathland.view.dsl.foregroundStyle
import dev.pathland.view.dsl.frame
import dev.pathland.view.dsl.navigate
import dev.pathland.view.dsl.navigator
import dev.pathland.view.dsl.padding
import dev.pathland.view.dsl.plainButtonStyle
import dev.pathland.view.dsl.scaledToFit
import dev.pathland.view.dsl.windowMetadata

/** The Kotlin-authored Pathland marketing + docs app. */
class DocsSite : PathlandApp {

    private val repository: DocsRepository = DocsRepository.fromResources()

    override fun newRoot(): View {
        val pages = repository.pages
        val docsHome = pages.first().route
        val router = navigator("/") {
            route("/", MarketingPage(docsHome))
            for (page in pages) {
                route(page.route, DocsLayout(page, repository))
            }
            fallback(NotFoundPage())
        }
        return NavigationStack(router)
    }

    override fun pageMetadata(request: PageMetadataRequest): PageMetadata {
        val route = request.route()
        val page = repository.page(route)
        return if (page != null) {
            PageMetadata.builder()
                .title("${page.title} · Pathland")
                .description(page.description)
                .ogType("article")
                .imageUrl(page.image)
                .build()
        } else {
            PageMetadata.builder()
                .title("Pathland — the declarative UI protocol")
                .description(
                    "Write UI once in Kotlin, Rust, or any host; emit a 16-byte " +
                        "opcode stream and render native elements everywhere.",
                )
                .ogType("website")
                .build()
        }
    }
}

private class MarketingPage(private val docsHome: String) : View {
    override fun renderNode(env: dev.pathland.view.core.Environment): dev.pathland.view.engine.PathlandNode =
        page().renderNode(env)

    private fun page(): View = VStack(spacing = 0f) {
        Header(docsHome)
        VStack(spacing = 24f) {
            HStack(alignment = VerticalAlignment.CENTER, spacing = 40f) {
                VStack(alignment = HorizontalAlignment.LEADING, spacing = 16f) {
                    Text("Write UI once.\nRender it everywhere.")
                        .font(Font.largeTitle())
                        .fontWeight(FontWeight.BOLD)
                    Text(
                        "Pathland is an open, binary UI protocol. Describe WHAT the UI is " +
                            "with a retained, declarative view tree — a 16-byte opcode stream " +
                            "renders it with native elements on web, desktop, and beyond.",
                    ).fontSize(18f)
                        .foregroundStyle(Color.token("color.text.secondary"))
                    HStack(spacing = 12f) {
                        Cta("Read the docs", docsHome, primary = true)
                        Cta("View on GitHub", docsHome, primary = false)
                    }
                }.frame { maxWidth(620f) }
                Image("/docs-assets/screenshot_browser.png")
                    .scaledToFit()
                    .frame { maxWidth(520f) }
                    .border(Color.token("color.border"), 1f, 12f)
            }
            .padding(top = 56f, right = 40f, bottom = 24f, left = 40f)
            .frame { maxWidth(1240f) }

            Grid(columns = 3, spacing = 16f) {
                Feature(
                    "16-byte opcodes",
                    "Every instruction is fixed-size and cache-line friendly. Four fit in a 64-byte line.",
                )
                Feature(
                    "Declarative, not positioned",
                    "VStack, HStack, Text, spacing, padding — the engine never computes layout or emits rects.",
                )
                Feature(
                    "Reactive deltas",
                    "Only changed nodes emit opcodes. An unchanged tree emits zero bytes.",
                )
                Feature(
                    "Kotlin DSL",
                    "SwiftUI-shaped builders, signals, state, routing, media, and Markdown docs.",
                )
                Feature(
                    "Native elements",
                    "GTK4 widgets, DOM, Qt Quick — each renderer maps opcodes to its own native elements.",
                )
                Feature(
                    "Server to client",
                    "SSR first paint, then live deltas over a binary WebSocket protocol.",
                )
            }
            .padding(right = 40f, left = 40f)
            .frame { maxWidth(1240f) }

            Divider().padding(right = 40f, left = 40f)

            VStack(spacing = 12f) {
                Text("Start with the protocol, stay for the DSL.")
                    .font(Font.title())
                    .fontWeight(FontWeight.BOLD)
                Text("The documentation is written in Markdown and rendered through the Kotlin DSL.")
                    .foregroundStyle(Color.token("color.text.secondary"))
                Cta("Open the documentation", docsHome, primary = true)
            }.padding(40f)
        }
        Footer()
    }.windowMetadata {
        title("Pathland — the declarative UI protocol")
        description(
            "Write UI once and render native elements everywhere with a 16-byte " +
                "opcode protocol.",
        )
    }

    private fun Header(docsHome: String) {
        HStack(alignment = VerticalAlignment.CENTER, spacing = 16f) {
            Text("Pathland").font(Font.headline()).fontWeight(FontWeight.BOLD)
            Spacer()
            Cta("Docs", docsHome, primary = false)
            Text("[GitHub](https://github.com/PathlandDev/Pathland)")
                .fontSize(14f)
                .foregroundStyle(Color.token("color.text.secondary"))
        }
        .padding(top = 14f, right = 40f, bottom = 14f, left = 40f)
        .background(Color.token("color.surface"))
        .accessibilityRole(Roles.BANNER)
    }

    private fun Footer() {
        VStack(spacing = 8f) {
            Divider()
            Text("Pathland is open source under the Apache 2.0 license.")
                .fontSize(12f)
                .foregroundStyle(Color.token("color.text.secondary"))
                .padding(24f)
        }
    }

    private fun Feature(title: String, body: String) {
        VStack(alignment = HorizontalAlignment.LEADING, spacing = 8f) {
            Text(title).font(Font.headline()).fontWeight(FontWeight.SEMIBOLD)
            Text(body).fontSize(14f).foregroundStyle(Color.token("color.text.secondary"))
        }
        .padding(18f)
        .background(Color.token("color.surface"))
        .border(Color.token("color.border"), 1f, 10f)
    }

    private fun Cta(label: String, route: String, primary: Boolean) {
        Button(label) {}
            .buttonStyle(plainButtonStyle())
            .fontSize(14f)
            .fontWeight(if (primary) FontWeight.SEMIBOLD else FontWeight.REGULAR)
            .padding(top = 9f, right = 14f, bottom = 9f, left = 14f)
            .background(
                if (primary) Color.token("color.primary") else Color.token("color.surface"),
            )
            .foregroundStyle(
                if (primary) Color.token("color.text.onPrimary") else Color.token("color.text.primary"),
            )
            .border(Color.token("color.border"), 1f, 8f)
            .navigate(route)
    }
}

private class NotFoundPage : View {
    override fun renderNode(env: dev.pathland.view.core.Environment): dev.pathland.view.engine.PathlandNode =
        VStack(spacing = 16f) {
            Text("Not found").font(Font.largeTitle())
            Text("That page does not exist.")
            Button("Back to the docs") {}.buttonStyle(plainButtonStyle()).navigate("/docs")
        }.padding(40f).renderNode(env)
}

