data class ComponentDoc(
    val name: String,
    val slug: String,
    val summary: String,
    val declaration: String,
    val overview: String = "",
    val properties: List<DocProperty> = emptyList(),
    val examples: List<DocExample> = emptyList(),
    val notes: List<String> = emptyList(),
    val platforms: List<String> = listOf("Web", "GTK", "Qt"),
    val related: List<String> = emptyList(),
    val demo: (() -> View)? = null,
) {
