+package dev.pathland.demo.docs
+
+import dev.pathland.docs.DocsRepository
+import org.junit.jupiter.api.Assertions.assertTrue
+import org.junit.jupiter.api.Test
+
+class DocsContentTest {
+
+    private val repository = DocsRepository.fromResources()
+    private val liveFence = Regex("(?m)^```[^\\n]*\\blive=([^\\s`]+)")
+
+    @Test
+    fun everyLiveExampleHasARegisteredView() {
+        val missing = repository.pages.flatMap { page ->
+            liveFence.findAll(page.markdown).mapNotNull { match ->
+                val id = match.groupValues[1]
+                if (id in LiveExamples.byId) null else "${page.sourcePath}: $id"
+            }
+        }
+        assertTrue(missing.isEmpty(), "unregistered live examples: $missing")
+    }
+
+    @Test
+    fun componentAndModifierSectionsArePresent() {
+        assertTrue(repository.page("/docs/components") != null)
+        assertTrue(repository.page("/docs/modifiers") != null)
+        assertTrue(repository.page("/docs/components/text") != null)
+        assertTrue(repository.page("/docs/modifiers/padding") != null)
+    }
+
+    @Test
+    fun allLiveFenceIdsAreUniquePerPage() {
+        val duplicates = repository.pages.flatMap { page ->
+            liveFence.findAll(page.markdown)
+                .map { it.groupValues[1] }
+                .groupingBy { it }
+                .eachCount()
+                .filterValues { it > 1 }
+                .keys
+                .map { "${page.sourcePath}: $it" }
+        }
+        assertTrue(duplicates.isEmpty(), "duplicate live ids: $duplicates")
+    }
+}

