            reapplyZStackAlignment(kv.first);
        }
    }
    // A HUG_CONTENT axis on a ScrollView sizes the viewport to its content.
    for (auto &kv : g.components) {
        if (kv.second == PL_COMP_SCROLL) {
            reconcileScrollSize(kv.first);
        }
    }
}

