            text: None,
            properties: props.iter().copied().collect(),
            strings: strings
                .iter()
                .map(|(k, v)| (*k, v.to_string()))
                .collect(),
            token_refs: Default::default(),
            date: None,
            children: Vec::new(),
            fit_thresholds: Vec::new(),
        }
    }

    fn f32_bits(v: f32) -> u32 {
        v.to_bits()
    }

