     override fun body(content: View): View = Modified.props(
         content,
         Modified.prop(Properties.CLIPS_TO_BOUNDS, 1),
         Modified.prop(Properties.SHAPE_KIND, shape),
     )
     companion object {
         fun of(shape: ShapeKind) = ClipShape(Signals.constant(shape))
