-        if let Some(v) = f32p(property_id::WHITE_SPACE) {
-            css.push_str(&format!(
-                "white-space:{};",
-                match v as u8 {
-                    1 => "nowrap",
-                    2 => "pre",
-                    3 => "pre-wrap",
-                    _ => "normal",
-                }
-            ));
-        }
