     FakeSocket.instances.push(this);
   }
   send(data: Uint8Array): void {
     this.sent.push(data);
   }
   close(): void {
     this.readyState = 3; // CLOSED
     this.onclose?.();
   }
   emitOpen(): void {
     this.readyState = 1; // OPEN
     this.onopen?.();
   }
   emitMessage(data: unknown): void {
     this.onmessage?.({ data });
   }
