 if (parentMain === null) { el.style.flex = "1 1 auto"; if (el.style.alignSelf === "") el.style.alignSelf="stretch"; }
 else if (parentMain === scrollH) { el.style.flex = "1 1 auto"; }
 else { el.style.flex = ""; }
}
```
